// Arquivo completo para: src/api/axios.js

import axios from 'axios';

// Cria uma instância do Axios com a URL base da sua API
const instance = axios.create({
    baseURL: 'http://localhost:8000/api' 
} );

// ADICIONADO: Interceptador de Respostas
// Esta função será chamada para cada resposta que o Axios receber.
instance.interceptors.response.use(
    // 1. Função para respostas de sucesso (status 2xx)
    // Apenas retorna a resposta, não fazemos nada aqui.
    (response) => {
        return response;
    },
    // 2. Função para respostas de erro
    (error) => {
        // Verifica se o erro existe e se a resposta tem o status 401
        if (error.response && error.response.status === 401) {
            
            // Limpa o armazenamento local, pois os dados do usuário não são mais válidos
            localStorage.removeItem('token');
            localStorage.removeItem('userData');
            
            // Recarrega a página. Como o token foi removido, o App.js
            // vai renderizar a tela de login/home para deslogados.
            // Isso efetivamente "desloga" o usuário.
            window.location.href = '/login'; // Redireciona para a tela de login

            // Você pode também mostrar um alerta
            alert("Sua sessão expirou. Por favor, faça login novamente.");
        }
        
        // Retorna a promessa rejeitada para que o erro possa ser tratado
        // localmente no componente, se necessário (ex: para mostrar "Erro ao carregar").
        return Promise.reject(error);
    }
);

export default instance;
